import React from "react";
import { useParams, useLocation } from "react-router-dom";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";

/* ---------- Styles ---------- */
const PageWrapper = styled.div`
  background-color: ${({ theme }) => theme.colors.background};
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 90%;
  max-width: 1300px;
  padding: 60px 0;
  display: flex;
  flex-direction: column;
  gap: 24px;
`;

const Header = styled.div`
  display: flex;
  align-items: center;
  gap: 24px;
  background-color: #fff;
  border-radius: 12px;
  padding: 32px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
`;

const SalonImage = styled.img`
  width: 220px;
  height: 160px;
  border-radius: 12px;
  object-fit: cover;
`;

const SalonDetails = styled.div`
  display: flex;
  flex-direction: column;
  gap: 8px;
`;

const SalonName = styled.h1`
  font-size: 28px;
  font-weight: 700;
  color: #0b1c36;
`;

const SalonLocation = styled.p`
  font-size: 16px;
  color: #7a7a7a;
`;

const SalonRating = styled.p`
  font-size: 16px;
  color: #333;
  font-weight: 600;
`;

const Description = styled.p`
  font-size: 16px;
  color: #555;
  line-height: 1.6;
  margin-top: 12px;
`;

/* ---------- Component ---------- */
const BusinessPage: React.FC = () => {
  const { salonId } = useParams();
  const location = useLocation();
  const salon = location.state;

  // ✅ fallback for direct access without state
  if (!salon) {
    return (
      <PageWrapper>
        <TabBar type="customer" />
        <ContentWrapper>
          <h2 style={{ color: "#333" }}>
            No salon data available for ID: {salonId}
          </h2>
          <p style={{ color: "#666" }}>
            Try navigating through the homepage again.
          </p>
        </ContentWrapper>
      </PageWrapper>
    );
  }

  return (
    <PageWrapper>
      <TabBar type="customer" />
      <ContentWrapper>
        <Header>
          <SalonImage src={salon.image} alt={salon.name} />
          <SalonDetails>
            <SalonName>{salon.name}</SalonName>
            <SalonLocation>{salon.location}</SalonLocation>
            <SalonRating>
              ⭐ {salon.rating} ({salon.reviews} reviews)
            </SalonRating>
          </SalonDetails>
        </Header>

        <Description>{salon.description || "Salon description goes here..."}</Description>
      </ContentWrapper>
    </PageWrapper>
  );
};

export default BusinessPage;
